"""Reproducible README assembly; no network and no HTML layout CSS."""
import json
from visual import ROOT,save

def img(src,alt,width='100%'):
    from html import escape
    return f'<img src="{src}" alt="{escape(alt,quote=True)}" width="{width}" />'

def picture(src,mobile,alt):
    return '<picture>\n'+f'  <source media="(max-width: 600px)" srcset="{mobile}" />\n  '+img(src,alt)+'\n</picture>'

def main():
    ps=json.loads((ROOT/'data/projects.json').read_text(encoding='utf-8'))
    parts=['<!-- Generated by scripts/assemble_readme.py. Edit data/projects.json or the assembly source. -->',picture('assets/hero/hero.svg','assets/hero/mobile.svg','ZYLUS — Saksham Kumar Mishra. Building the machinery beneath the abstraction.')]
    links=[('portfolio','Portfolio','https://sakshamkumarmishra.cv'),('repositories','Public repositories','https://github.com/Zylus08?tab=repositories'),('linkedin','LinkedIn','https://www.linkedin.com/in/saksham-mishra-ml/'),('cv','Academic CV (PDF)','https://sakshamkumarmishra.cv/documents/Saksham_Mishra_CV.pdf'),('email','Email Saksham','mailto:mishrasaksham080705@gmail.com')]
    parts+=['<p>\n'+'\n'.join(f'<a href="{url}">{img("assets/navigation/"+name+".svg",label,"184")}</a>' for name,label,url in links)+'\n</p>']
    parts+=['## 01 / Operator profile', '**I build systems to understand them.** Query engines, language runtimes, CPU learning systems—and experiments at the intersection of computation, physical laws and markets. I’m Saksham Kumar Mishra, a computer engineering undergraduate approaching engineering as inquiry.', '[Systems](#02--systems-from-first-principles) · [Intelligence](#03--machine-intelligence) · [Quant](#04--quantitative-laboratory) · [Telemetry](#06--developer-telemetry)', '## 02 / Systems from first principles', 'Four investigations into the machinery beneath familiar abstractions. Open a dossier to inspect the implementation, tests and limitations.']
    def posters(domain):
        return '<p>\n'+'\n'.join(f'<a href="{p["url"]}">{img("assets/projects/"+p["repo"]+".svg",p["name"]+" — "+p["description"]+" "+p["status"]+". "+p["limitation"],"460")}</a>' for p in ps if p['domain']==domain)+'\n</p>'
    parts +=[posters('systems'),'**Boundaries matter.** AXIOM and PRAXIS implement deliberate language subsets. FORGE’s end-to-end acceleration target was **not achieved**. VECTRA’s sustained-throughput objective remains **partial**. Release labels describe repository milestones, not independent certification.','## 03 / Machine intelligence','From observations to models—and from models back to questions. These are engineering experiments and research investigations; no peer-review status is implied.',posters('intelligence'),'JANUS’s default-branch baseline uses handcrafted evaluation. RoadVision reports a small pilot evaluation. Aerospace RUL is an independent project, with no implied Rolls-Royce affiliation.','## 04 / Quantitative laboratory',picture('assets/research/quant.svg','assets/research/quant-mobile.svg','Uncertainty, made explicit. Risk, regimes and execution. Gaussian curves are mathematical illustrations, not market performance.'),posters('quant'),'Research infrastructure for asking better questions about risk and execution. No financial returns, live profitability or production trading readiness are claimed.','## 05 / Technology matrix','Tools represented in public project source and dependency manifests. A capability map, without proficiency scores.','<p>\n'+'\n'.join(img(f'assets/technology/matrix-{n:02}.svg',label,'460') for n,label in enumerate(['Languages: Python, C++, Rust, Go','Systems: CMake, Docker, Git, GitHub Actions','Machine and scientific computing: PyTorch, NumPy, pandas, scikit-learn','Applications: React, Vite, TypeScript, JavaScript'],1))+'\n</p>','Numerical work also includes SciPy, Jupyter, time-series modelling and reinforcement learning. [Technology evidence and icon licenses](reports/04_PROJECT_EVIDENCE.md).','## 06 / Developer telemetry','<p>\n'+img('assets/telemetry/repositories.svg','Public original repository counts, stars and forks, with primary-language distribution. Timestamp in panel; accessible values linked below.','460')+'\n'+img('assets/telemetry/activity.svg','Actual 365-day public profile contribution activity and window-bounded streaks. Accessible values linked below.','460')+'\n</p>','[Read the current snapshot and recent pushes](data/telemetry.md) · [How these metrics are measured](reports/06_TELEMETRY_AND_SKYLINE.md)\n\nRepository metrics exclude forks, archives and this profile repository. Language bars count primary repository languages, **not proficiency**. Contribution totals reflect the public profile calendar, which can include anonymized private activity if enabled. Weekly refreshes preserve the last valid timestamped snapshot on failure.','## 07 / Activity topography',picture('assets/skyline/skyline.svg','assets/skyline/mobile.svg','A year in relief: real daily GitHub contributions, arranged by calendar week and weekday. Building height is proportional to daily count. Data and dates are available in the linked snapshot.'),'[Calendar data and provenance](data/github_snapshot.json). The skyline includes every day in the displayed window, including zero-activity days.','## 08 / Computational frontiers',picture('assets/research/frontiers.svg','assets/research/frontiers-mobile.svg','Order from observation. A numerically integrated Lorenz attractor, projected into the x–z plane.'),'**Questions I want to pursue:** How can machines recover physical laws from observations? What survives noise, changing regimes and nonlinear dynamics? How can computational systems expose their own limits?\n\nThese are research interests. The artwork integrates the Lorenz equations using RK4; [equations, parameters and reproduction](reports/05_ASSET_GENERATION.md).','## 09 / End of transmission',img('assets/footer/signature.svg','Understand the abstraction. Then build what lies beneath it.','460'),'[Start a conversation](mailto:mishrasaksham080705@gmail.com) · [Explore the portfolio](https://sakshamkumarmishra.cv) · [Read the CV](https://sakshamkumarmishra.cv/documents/Saksham_Mishra_CV.pdf)\n\n<sub>Original computational artwork. Public evidence. Reproducible assets. [Behind the observatory](reports/10_FINAL_RELEASE_REPORT.md).</sub>']
    save('README.md','\n\n'.join(parts)+'\n')

if __name__=='__main__':main()
